do {
    quest_entry_original_t *spawn = &spawns[wave + 1];
    if (wave % 2 == 0) {
        spawn->pos.x = -128.0f;
    } else {
        spawn->pos.x = 1152.0f;
    }
    spawn->pos.y = (float)(terrain_texture_width / 2);
    spawn->set_spawn(
        SPAWN_ID_FORMATION_RING_ALIEN_5_19,
        trigger_time_ms,
        one);

    ++wave;
    trigger_time_ms += 2500;
} while (trigger_time_ms < 32500);

